245	            .join("dns-proxy");
246	        std::fs::create_dir_all(&config_dir).ok();
247	        config_dir.join("config.toml")
248	    }
249	
250	    pub fn load() -> Self {
251	        let path = Self::config_path();
252	        let mut config = if path.exists() {
253	            let content = std::fs::read_to_string(&path).unwrap_or_default();
254	            toml::from_str(&content).unwrap_or_default()
255	        } else {
256	            Self::default()
257	        };
258	        config.migrate();
259	        config
260	    }
261	
262	    /// 迁移旧配置：合并 foreign 到 proxy，更新分组描述
263	    fn migrate(&mut self) {
264	        let mut changed = false;
265	
266	        // 将 upstream 中 group="foreign" 改为 "proxy"
267	        for server in &mut self.upstream {
268	            if server.group == "foreign" {
269	                server.group = "proxy".to_string();
270	                changed = true;
271	            }
272	        }
273	
274	        // 将订阅中 target_group="foreign" 改为 "proxy"
275	        for sub in &mut self.subscriptions {
276	            if sub.target_group.as_deref() == Some("foreign") {
277	                sub.target_group = Some("proxy".to_string());
278	                changed = true;
279	            }
280	        }
281	
282	        // 移除 foreign 分组
283	        let before = self.server_groups.len();
284	        self.server_groups.retain(|g| g.name != "foreign");
285	        if self.server_groups.len() != before {
286	            changed = true;
287	        }
288	
289	        // 更新分组描述
290	        for group in &mut self.server_groups {
291	            match group.name.as_str() {
292	                "domestic" => {
293	                    if group.description != "直连" {
294	                        group.description = "直连".to_string();
295	                        changed = true;
296	                    }
297	                }
298	                "proxy" => {
299	                    if group.description != "代理" {
300	                        group.description = "代理".to_string();
301	                        changed = true;
302	                    }
303	                }
304	                _ => {}
305	            }
306	        }
307	
308	        // 确保 domestic 和 proxy 分组存在
309	        if !self.server_groups.iter().any(|g| g.name == "domestic") {
310	            self.server_groups.push(ServerGroup { name: "domestic".to_string(), description: "直连".to_string() });
311	            changed = true;
312	        }
313	        if !self.server_groups.iter().any(|g| g.name == "proxy") {
314	            self.server_groups.push(ServerGroup { name: "proxy".to_string(), description: "代理".to_string() });
315	            changed = true;
316	        }
317	
318	        if changed {
319	            self.save().ok();
320	        }
321	    }
322	
323	    pub fn save(&self) -> anyhow::Result<()> {
324	        let path = Self::config_path();
325	        let content = toml::to_string_pretty(self)?;
326	        std::fs::write(path, content)?;
327	        Ok(())
328	    }
329	}
