5	use config::AppConfig;
6	use dns::server::DnsServer;
7	use dns::{CacheStats, DnsQueryLog, DnsStats, TrafficStats};
8	use std::sync::Arc;
9	use tauri::menu::{MenuBuilder, MenuItemBuilder};
10	use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
11	use tauri::{Manager, State};
12	use tokio::sync::Mutex;
13	use tun::device::TunDevice;
14	use tun::dns_intercept::DnsInterceptor;
15	use tun::{TunConfig, TunStatus};
16	
17	pub struct AppState {
18	    server: Arc<Mutex<DnsServer>>,
19	    config: Arc<Mutex<AppConfig>>,
20	    tun_device: Arc<Mutex<TunDevice>>,
21	    tun_config: Arc<Mutex<TunConfig>>,
22	    tun_starting: Arc<Mutex<bool>>,
23	    latency_results: Arc<Mutex<Vec<DnsLatencyResult>>>,
24	    latency_last_test: Arc<Mutex<Option<String>>>,
25	}
26	
27	#[tauri::command]
28	async fn get_config(state: State<'_, AppState>) -> Result<AppConfig, String> {
29	    let config = state.config.lock().await;
30	    Ok(config.clone())
31	}
32	
33	#[tauri::command]
34	async fn save_config(state: State<'_, AppState>, new_config: AppConfig) -> Result<(), String> {
35	    let mut config = state.config.lock().await;
36	    *config = new_config.clone();
37	    config.save().map_err(|e| e.to_string())?;
38	
39	    // 重启服务器以应用新配置
40	    let mut server = state.server.lock().await;
41	    if server.is_running().await {
42	        server.stop().await;
43	        // 等待端口释放
44	        tokio::time::sleep(std::time::Duration::from_millis(300)).await;
45	        *server = DnsServer::new(config.clone());
46	        server.start().await.map_err(|e| e.to_string())?;
47	    } else {
48	        *server = DnsServer::new(config.clone());
49	    }
50	
51	    Ok(())
52	}
53	
54	#[tauri::command]
55	async fn start_server(state: State<'_, AppState>) -> Result<(), String> {
56	    let mut server = state.server.lock().await;
57	    server.start().await.map_err(|e| e.to_string())?;
58	    Ok(())
59	}
60	
61	#[tauri::command]
62	async fn stop_server(state: State<'_, AppState>) -> Result<(), String> {
63	    let mut server = state.server.lock().await;
64	    server.stop().await;
65	    Ok(())
66	}
67	
68	#[tauri::command]
69	async fn get_server_status(state: State<'_, AppState>) -> Result<bool, String> {
70	    let server = state.server.lock().await;
71	    Ok(server.is_running().await)
72	}
73	
74	#[tauri::command]
75	async fn get_stats(state: State<'_, AppState>) -> Result<DnsStats, String> {
76	    let server = state.server.lock().await;
77	    let (total, blocked, cached, avg_latency) = server.get_stats();
78	    let is_running = server.is_running().await;
79	
80	    Ok(DnsStats {
81	        total_queries: total,
82	        blocked_queries: blocked,
83	        cached_queries: cached,
84	        avg_latency,
85	        is_running,
86	    })
87	}
88	
89	#[tauri::command]
90	async fn get_logs(state: State<'_, AppState>) -> Result<Vec<DnsQueryLog>, String> {
91	    let server = state.server.lock().await;
92	    Ok(server.get_logs())
93	}
94	
95	#[tauri::command]
96	async fn clear_logs(state: State<'_, AppState>) -> Result<(), String> {
97	    let server = state.server.lock().await;
98	    server.clear_logs();
99	    Ok(())
100	}
101	
102	#[tauri::command]
103	async fn clear_cache(state: State<'_, AppState>) -> Result<(), String> {
104	    let server = state.server.lock().await;
105	    server.clear_cache();
106	    Ok(())
107	}
108	
109	#[tauri::command]
110	async fn get_traffic_stats(state: State<'_, AppState>) -> Result<TrafficStats, String> {
111	    let server = state.server.lock().await;
112	    Ok(server.get_traffic_stats())
113	}
114	
115	#[tauri::command]
116	async fn get_cache_stats(state: State<'_, AppState>) -> Result<CacheStats, String> {
117	    let server = state.server.lock().await;
118	    Ok(server.get_cache_stats())
119	}
120	
121	#[tauri::command]
122	async fn update_subscriptions(state: State<'_, AppState>) -> Result<String, String> {
123	    let server = state.server.lock().await;
124	    server.update_subscriptions().await;
125	
126	    // 同步更新 AppState 中的配置
127	    let new_config = server.get_config().await;
128	    let mut config = state.config.lock().await;
129	    *config = new_config;
130	
131	    Ok("订阅已更新".to_string())
132	}
133	
134	// TUN 相关命令
135	
136	#[tauri::command]
137	async fn get_tun_config(state: State<'_, AppState>) -> Result<TunConfig, String> {
138	    let config = state.tun_config.lock().await;
139	    Ok(config.clone())
140	}
141	
142	#[tauri::command]
143	async fn save_tun_config(state: State<'_, AppState>, new_config: TunConfig) -> Result<(), String> {
144	    let mut tun_config = state.tun_config.lock().await;
145	    *tun_config = new_config.clone();
146	    drop(tun_config);
147	
148	    // 同步保存到主配置文件
149	    let mut app_config = state.config.lock().await;
150	    app_config.tun = new_config;
151	    app_config.save().map_err(|e| e.to_string())?;
152	
153	    Ok(())
154	}
155	
156	#[tauri::command]
157	async fn start_tun(state: State<'_, AppState>) -> Result<String, String> {
158	    let config = state.tun_config.lock().await;
159	    if !config.enabled {
160	        return Err("TUN模式未启用，请在配置中启用".to_string());
161	    }
162	    let tun_config = config.clone();
163	    drop(config);
164	
165	    // 检查是否已在启动中
166	    {
167	        let starting = state.tun_starting.lock().await;
168	        if *starting {
169	            return Ok("TUN正在启动中...".to_string());
170	        }
171	    }
172	
173	    // 设置启动中状态
174	    {
175	        let mut starting = state.tun_starting.lock().await;
176	        *starting = true;
177	    }
178	
179	    // 克隆需要的 Arc 字段
180	    let tun_device = state.tun_device.clone();
181	    let tun_starting = state.tun_starting.clone();
182	    let server = state.server.clone();
183	
184	    // 异步启动TUN
185	    tokio::spawn(async move {
186	        let result = start_tun_internal(tun_device.clone(), server, tun_config).await;
187	        let mut starting = tun_starting.lock().await;
188	        *starting = false;
189	
190	        match result {
191	            Ok(_) => tracing::info!("TUN异步启动完成"),
192	            Err(e) => tracing::error!("TUN异步启动失败: {}", e),
193	        }
194	    });
195	
196	    Ok("TUN正在启动...".to_string())
197	}
198	
199	async fn start_tun_internal(
200	    tun_device: Arc<Mutex<TunDevice>>,
201	    server: Arc<Mutex<DnsServer>>,
202	    tun_config: TunConfig,
203	) -> Result<(), String> {
204	    let mut tun = tun_device.lock().await;
205	
206	    // 更新TUN设备配置
207	    *tun = TunDevice::new(tun_config);
208	
209	    // 启动TUN设备
210	    tun.start().await.map_err(|e| e.to_string())?;
211	
212	    // 启动DNS拦截器
213	    let tun_clone = tun_device.clone();
214	    drop(tun);
215	    let server = server.lock().await;
216	    let handler = server.get_dns_handler();
217	    let interceptor = DnsInterceptor::new(tun_clone);
218	    interceptor.start(handler).await;
219	
220	    Ok(())
221	}
222	
223	#[tauri::command]
224	async fn stop_tun(state: State<'_, AppState>) -> Result<String, String> {
225	    let mut tun = state.tun_device.lock().await;
226	    tun.stop().await;
227	    Ok("TUN设备已停止".to_string())
228	}
229	
230	#[tauri::command]
231	async fn get_tun_status(state: State<'_, AppState>) -> Result<TunStatus, String> {
232	    let tun = state.tun_device.lock().await;
233	    let config = state.tun_config.lock().await;
234	    let starting = state.tun_starting.lock().await;
235	
236	    let active = tun.is_running().await;
237	
238	    Ok(TunStatus {
239	        active,
240	        starting: *starting,
241	        interface_name: if active { config.interface_name.clone() } else { String::new() },
242	        ip_address: if active { config.gateway.clone() } else { String::new() },
243	        dns_redirected: active,
244	        packets_processed: 0,
245	    })
246	}
247	
248	#[derive(serde::Serialize, Clone)]
249	struct DnsLatencyResult {
