293	/// 检查 GitHub 是否有新版本
294	#[tauri::command]
295	async fn check_update() -> Result<UpdateInfo, String> {
296	    let current_version = env!("CARGO_PKG_VERSION").to_string();
297	
298	    // 调用 GitHub API 获取最新 release（支持系统代理）
299	    let mut builder = reqwest::Client::builder()
300	        .timeout(std::time::Duration::from_secs(15))
301	        .user_agent("dns-proxy")
302	        .danger_accept_invalid_certs(false);
303	
304	    // 尝试使用系统代理
305	    if let Ok(proxy_url) = std::env::var("HTTP_PROXY").or_else(|_| std::env::var("http_proxy")) {
306	        if let Ok(proxy) = reqwest::Proxy::http(&proxy_url) {
307	            builder = builder.proxy(proxy);
308	        }
309	    }
310	    if let Ok(proxy_url) = std::env::var("HTTPS_PROXY").or_else(|_| std::env::var("https_proxy")) {
311	        if let Ok(proxy) = reqwest::Proxy::https(&proxy_url) {
312	            builder = builder.proxy(proxy);
313	        }
314	    }
315	
316	    let client = builder
317	        .build()
318	        .map_err(|e| format!("创建 HTTP 客户端失败: {}", e))?;
319	
320	    let url = "https://api.github.com/repos/PVPWHGAMES/dns-proxy/releases/latest";
321	    let response = client
322	        .get(url)
323	        .send()
324	        .await
325	        .map_err(|e| format!("请求 GitHub API 失败，请检查网络连接或代理设置: {}", e))?;
326	
327	    if !response.status().is_success() {
328	        return Err(format!("GitHub API 返回错误: {}", response.status()));
329	    }
330	
331	    let release: serde_json::Value = response
332	        .json()
333	        .await
334	        .map_err(|e| format!("解析响应失败: {}", e))?;
335	
336	    let latest_version = release["tag_name"]
337	        .as_str()
338	        .unwrap_or("v0.0.0")
339	        .trim_start_matches('v')
340	        .to_string();
341	
342	    let release_url = release["html_url"]
343	        .as_str()
344	        .unwrap_or("")
345	        .to_string();
346	
347	    let release_notes = release["body"]
348	        .as_str()
349	        .unwrap_or("无更新说明")
350	        .to_string();
351	
352	    let published_at = release["published_at"]
353	        .as_str()
354	        .unwrap_or("")
355	        .to_string();
356	
357	    // 比较版本号
358	    let has_update = compare_versions(&current_version, &latest_version);
359	
360	    Ok(UpdateInfo {
361	        has_update,
362	        current_version,
363	        latest_version,
364	        release_url,
365	        release_notes,
366	        published_at,
367	    })
368	}
