370	/// 比较版本号，如果 latest > current 返回 true
371	fn compare_versions(current: &str, latest: &str) -> bool {
372	    let parse_version = |v: &str| -> Vec<u32> {
373	        v.split('.')
374	            .filter_map(|s| s.parse().ok())
375	            .collect()
376	    };
377	
378	    let current_parts = parse_version(current);
379	    let latest_parts = parse_version(latest);
380	
381	    for i in 0..std::cmp::max(current_parts.len(), latest_parts.len()) {
382	        let c = current_parts.get(i).copied().unwrap_or(0);
383	        let l = latest_parts.get(i).copied().unwrap_or(0);
384	        if l > c {
385	            return true;
386	        }
387	        if l < c {
388	            return false;
389	        }
390	    }
391	
392	    false
393	}
