395	async fn run_latency_test(servers: &[crate::config::DnsServer]) -> Vec<DnsLatencyResult> {
396	    let mut results = Vec::new();
397	
398	    // 创建优化的 HTTP 客户端（连接池）
399	    let http_client = reqwest::Client::builder()
400	        .timeout(std::time::Duration::from_secs(3))
401	        .pool_max_idle_per_host(8)
402	        .pool_idle_timeout(std::time::Duration::from_secs(90))
403	        .build()
404	        .unwrap_or_default();
405	
406	    for server in servers {
407	        let name = server.name.clone();
408	        let ip = server.ip.clone();
409	        let addr = format!("{}:{}", server.ip, server.port);
410	
411	        // 构造DNS查询请求 (查询 example.com A记录)
412	        let query = build_dns_query("example.com");
413	
414	        let start = std::time::Instant::now();
415	        let result = match server.protocol {
416	            crate::config::DnsProtocol::Udp | crate::config::DnsProtocol::Tcp => {
417	                // UDP/TCP 测试
418	                match tokio::net::UdpSocket::bind("0.0.0.0:0").await {
419	                    Ok(socket) => {
420	                        if let Err(e) = socket.connect(&addr).await {
421	                            Err(format!("连接失败: {}", e))
422	                        } else {
423	                            match socket.send(&query).await {
424	                                Ok(_) => {
425	                                    let mut buf = vec![0u8; 512];
426	                                    match tokio::time::timeout(
427	                                        std::time::Duration::from_secs(2),
428	                                        socket.recv(&mut buf),
429	                                    )
430	                                    .await
431	                                    {
432	                                        Ok(Ok(len)) => Ok(buf[..len].to_vec()),
433	                                        Ok(Err(e)) => Err(format!("接收失败: {}", e)),
434	                                        Err(_) => Err("超时".to_string()),
435	                                    }
436	                                }
437	                                Err(e) => Err(format!("发送失败: {}", e)),
438	                            }
439	                        }
440	                    }
441	                    Err(e) => Err(format!("绑定失败: {}", e)),
442	                }
443	            }
444	            crate::config::DnsProtocol::Doh => {
445	                // DoH 测试 - 复用连接池
446	                let url = server
447	                    .doh_url
448	                    .as_deref()
449	                    .unwrap_or("https://cloudflare-dns.com/dns-query");
450	                match http_client
451	                    .post(url)
452	                    .header("Content-Type", "application/dns-message")
453	                    .header("Accept", "application/dns-message")
454	                    .body(query.clone())
455	                    .send()
456	                    .await
457	                {
458	                    Ok(resp) => match resp.bytes().await {
459	                        Ok(bytes) => Ok(bytes.to_vec()),
460	                        Err(e) => Err(format!("读取响应失败: {}", e)),
461	                    },
462	                    Err(e) => Err(format!("请求失败: {}", e)),
463	                }
464	            }
465	            crate::config::DnsProtocol::Dot => {
466	                // DoT 测试 - 使用 TLS 连接
467	                let dot_port = if server.port == 53 { 853 } else { server.port };
468	                test_dot_connection(&server.ip, dot_port, &query).await
469	            }
470	        };
471	
472	        let latency = start.elapsed().as_millis() as u64;
473	
474	        match result {
475	            Ok(_) => {
476	                results.push(DnsLatencyResult {
477	                    name,
478	                    ip,
479	                    latency_ms: Some(latency),
480	                    error: None,
481	                });
482	            }
483	            Err(e) => {
484	                results.push(DnsLatencyResult {
485	                    name,
486	                    ip,
487	                    latency_ms: None,
488	                    error: Some(e),
489	                });
490	            }
491	        }
492	    }
493	
494	    // 按延迟排序
495	    results.sort_by(|a, b| {
496	        a.latency_ms
497	            .unwrap_or(u64::MAX)
498	            .cmp(&b.latency_ms.unwrap_or(u64::MAX))
499	    });
500	
501	    results
502	}
