504	/// 测试 DoT (DNS-over-TLS) 连接
505	async fn test_dot_connection(ip: &str, port: u16, query: &[u8]) -> Result<Vec<u8>, String> {
506	    use tokio::io::{AsyncReadExt, AsyncWriteExt};
507	    use tokio::net::TcpStream;
508	    use tokio_rustls::TlsConnector;
509	
510	    let addr = format!("{}:{}", ip, port);
511	
512	    // 建立 TCP 连接
513	    let tcp = match tokio::time::timeout(std::time::Duration::from_secs(3), TcpStream::connect(&addr)).await {
514	        Ok(Ok(stream)) => stream,
515	        Ok(Err(e)) => return Err(format!("TCP连接失败: {}", e)),
516	        Err(_) => return Err("TCP连接超时".to_string()),
517	    };
518	
519	    // 配置 TLS
520	    let mut root_store = rustls::RootCertStore::empty();
521	    root_store.extend(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
522	    let config = rustls::ClientConfig::builder()
523	        .with_root_certificates(root_store)
524	        .with_no_client_auth();
525	
526	    let connector = TlsConnector::from(std::sync::Arc::new(config));
527	
528	    // TLS 握手
529	    let domain = rustls::pki_types::ServerName::try_from(ip.to_string())
530	        .map_err(|e| format!("无效域名: {}", e))?;
531	
532	    let mut tls = match tokio::time::timeout(std::time::Duration::from_secs(3), connector.connect(domain, tcp)).await {
533	        Ok(Ok(stream)) => stream,
534	        Ok(Err(e)) => return Err(format!("TLS握手失败: {}", e)),
535	        Err(_) => return Err("TLS握手超时".to_string()),
536	    };
537	
538	    // 发送 DNS 查询（DoT 使用 TCP 格式：2字节长度前缀 + 查询数据）
539	    let len = (query.len() as u16).to_be_bytes();
540	    tls.write_all(&len).await.map_err(|e| format!("发送长度失败: {}", e))?;
541	    tls.write_all(query).await.map_err(|e| format!("发送查询失败: {}", e))?;
542	
543	    // 读取响应长度
544	    let mut len_buf = [0u8; 2];
545	    tls.read_exact(&mut len_buf).await.map_err(|e| format!("读取响应长度失败: {}", e))?;
546	    let resp_len = u16::from_be_bytes(len_buf) as usize;
547	
548	    if resp_len > 4096 {
549	        return Err(format!("响应长度异常: {}", resp_len));
550	    }
551	
552	    // 读取响应数据
553	    let mut resp_buf = vec![0u8; resp_len];
554	    match tokio::time::timeout(std::time::Duration::from_secs(3), tls.read_exact(&mut resp_buf)).await {
555	        Ok(Ok(_)) => Ok(resp_buf),
556	        Ok(Err(e)) => Err(format!("读取响应失败: {}", e)),
557	        Err(_) => Err("读取响应超时".to_string()),
558	    }
559	}
