561	fn build_dns_query(domain: &str) -> Vec<u8> {
562	    // 简单构造DNS查询包
563	    let mut packet = Vec::new();
564	
565	    // Transaction ID
566	    packet.extend_from_slice(&[0x12, 0x34]);
567	
568	    // Flags: standard query
569	    packet.extend_from_slice(&[0x01, 0x00]);
570	
571	    // Questions: 1
572	    packet.extend_from_slice(&[0x00, 0x01]);
573	
574	    // Answer RRs: 0
575	    packet.extend_from_slice(&[0x00, 0x00]);
576	
577	    // Authority RRs: 0
578	    packet.extend_from_slice(&[0x00, 0x00]);
579	
580	    // Additional RRs: 0
581	    packet.extend_from_slice(&[0x00, 0x00]);
582	
583	    // Query name
584	    for part in domain.split('.') {
585	        packet.push(part.len() as u8);
586	        packet.extend_from_slice(part.as_bytes());
587	    }
588	    packet.push(0); // root label
589	
590	    // Query type: A (1)
591	    packet.extend_from_slice(&[0x00, 0x01]);
592	
593	    // Query class: IN (1)
594	    packet.extend_from_slice(&[0x00, 0x01]);
595	
596	    packet
597	}
