import { useState, useEffect } from "react";
import { Save, Plus, Trash2, Server, Wifi, Database, Zap, RefreshCw, Timer } from "lucide-react";
import { api, AppConfig, DnsServer, DnsProtocol, DnsStrategy, DnsLatencyResult, ServerGroup } from "../lib/api";

export default function Settings() {
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);
  const [latencyResults, setLatencyResults] = useState<DnsLatencyResult[]>([]);
  const [testingLatency, setTestingLatency] = useState(false);
  const [lastTestTime, setLastTestTime] = useState<string | null>(null);

  // 加载配置
  useEffect(() => {
    loadConfig();
    loadLatencyResults();
  }, []);

  const loadConfig = async () => {
    setLoading(true);
    try {
      const cfg = await api.getConfig();
      setConfig(cfg);
    } catch (e) {
      console.error("加载配置失败:", e);
      setMessage({ type: "error", text: "加载配置失败: " + e });
    } finally {
      setLoading(false);
    }
  };

  const loadLatencyResults = async () => {
    try {
      const [results, lastTest] = await api.getLatencyResults();
      setLatencyResults(results);
      setLastTestTime(lastTest);
    } catch (e) {
      console.error("加载延迟结果失败:", e);
    }
  };

  // 保存配置并自动重启服务
  const handleSave = async () => {
    if (!config) return;
    setSaving(true);
    setMessage(null);
    try {
      await api.saveConfig(config);

      // 自动重启服务使配置生效
      try {
        const isRunning = await api.getServerStatus();
        if (isRunning) {
          await api.stopServer();
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
        await api.startServer();
        setMessage({ type: "success", text: "配置已保存，服务已自动重启。" });
      } catch (restartErr) {
        setMessage({ type: "success", text: "配置已保存，但服务重启失败: " + restartErr });
      }
    } catch (e) {
      setMessage({ type: "error", text: "保存失败: " + e });
    } finally {
      setSaving(false);
    }
  };

  // 添加服务器
  const handleAddServer = () => {
    if (!config) return;
    const newServer: DnsServer = {
      name: "",
      ip: "",
      port: 53,
      enabled: true,
      protocol: "udp",
      doh_url: "",
      group: "default",
    };
    setConfig({
      ...config,
      upstream: [...config.upstream, newServer],
    });
  };

  // 切换协议时自动调整默认值
  const handleProtocolChange = (index: number, protocol: DnsProtocol) => {
    if (!config) return;
    const newUpstream = [...config.upstream];
    const server = { ...newUpstream[index] };
    server.protocol = protocol;

    // 根据协议设置合适的默认端口
    if (protocol === "dot") {
      server.port = 853;
    } else if (protocol === "doh") {
      server.port = 443;
    } else {
      server.port = 53;
    }

    newUpstream[index] = server;
    setConfig({ ...config, upstream: newUpstream });
  };

  // 删除服务器
  const handleRemoveServer = (index: number) => {
    if (!config) return;
    setConfig({
      ...config,
      upstream: config.upstream.filter((_, i) => i !== index),
    });
  };

  // 切换服务器启用状态
  const handleToggleServer = (index: number) => {
    if (!config) return;
    const newUpstream = [...config.upstream];
    newUpstream[index] = { ...newUpstream[index], enabled: !newUpstream[index].enabled };
    setConfig({ ...config, upstream: newUpstream });
  };

  // 更新服务器配置
  const handleServerChange = (index: number, field: keyof DnsServer, value: any) => {
    if (!config) return;
    const newUpstream = [...config.upstream];
    newUpstream[index] = { ...newUpstream[index], [field]: value };
    setConfig({ ...config, upstream: newUpstream });
  };

  // 测试DNS延迟
  const handleTestLatency = async () => {
    setTestingLatency(true);
    setLatencyResults([]);
    try {
      const results = await api.testDnsLatency();
      setLatencyResults(results);
      // 更新上次测试时间
      const now = new Date();
      setLastTestTime(`${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}`);
    } catch (e) {
      setMessage({ type: "error", text: "测试延迟失败: " + e });
    } finally {
      setTestingLatency(false);
    }
  };

  // 获取延迟显示颜色
  const getLatencyColor = (latencyMs?: number) => {
    if (!latencyMs) return "text-muted-foreground";
    if (latencyMs < 50) return "text-green-500";
    if (latencyMs < 100) return "text-yellow-500";
    return "text-red-500";
  };

  if (loading || !config) {
    return (
      <div className="flex items-center justify-center h-64">
        <RefreshCw className="w-8 h-8 animate-spin text-primary" />
        <span className="ml-2">加载配置中...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 消息提示 */}
      {message && (
        <div
          className={`p-4 rounded-lg ${
            message.type === "success"
              ? "bg-green-100 text-green-700 border border-green-200"
              : "bg-red-100 text-red-700 border border-red-200"
          }`}
        >
          {message.text}
        </div>
      )}

      {/* 监听设置 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center gap-2">
          <Wifi className="w-5 h-5 text-primary" />
          <h3 className="font-semibold">监听设置</h3>
        </div>
        <div className="p-4 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">监听地址</label>
              <input
                type="text"
                value={config.proxy.listen_address}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, listen_address: e.target.value },
                  })
                }
                className="w-full px-3 py-2 border rounded-lg bg-background"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2">监听端口</label>
              <input
                type="number"
                value={config.proxy.listen_port}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, listen_port: parseInt(e.target.value) || 53 },
                  })
                }
                className="w-full px-3 py-2 border rounded-lg bg-background"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">缓存大小</label>
              <input
                type="number"
                value={config.proxy.cache_size}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, cache_size: parseInt(e.target.value) || 1000 },
                  })
                }
                className="w-full px-3 py-2 border rounded-lg bg-background"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-2">缓存TTL (秒)</label>
              <input
                type="number"
                value={config.proxy.cache_ttl}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, cache_ttl: parseInt(e.target.value) || 300 },
                  })
                }
                className="w-full px-3 py-2 border rounded-lg bg-background"
              />
            </div>
          </div>

          <div className="space-y-3">
            <label className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={config.proxy.auto_start}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, auto_start: e.target.checked },
                  })
                }
                className="w-4 h-4"
              />
              <div>
                <p className="text-sm font-medium">开机自启动</p>
                <p className="text-xs text-muted-foreground">Windows 启动时自动运行</p>
              </div>
            </label>
            <label className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={config.proxy.block_ipv6}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, block_ipv6: e.target.checked },
                  })
                }
                className="w-4 h-4"
              />
              <div>
                <p className="text-sm font-medium">阻止 IPv6 查询</p>
                <p className="text-xs text-muted-foreground">屏蔽所有 AAAA 记录</p>
              </div>
            </label>
          </div>

          {/* ECS 配置 */}
          <div className="space-y-3 pt-3 border-t">
            <label className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={config.ecs?.enabled || false}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    ecs: { ...config.ecs, enabled: e.target.checked },
                  })
                }
                className="w-4 h-4"
              />
              <div>
                <p className="text-sm font-medium">启用 EDNS Client Subnet (ECS)</p>
                <p className="text-xs text-muted-foreground">传递客户端位置信息，让 CDN 返回更近的节点</p>
              </div>
            </label>

            {config.ecs?.enabled && (
              <div className="ml-7 space-y-3">
                <div>
                  <label className="block text-sm font-medium mb-2">客户端 IP</label>
                  <input
                    type="text"
                    value={config.ecs?.client_ip || ""}
                    onChange={(e) =>
                      setConfig({
                        ...config,
                        ecs: { ...config.ecs, client_ip: e.target.value || undefined },
                      })
                    }
                    placeholder="留空自动获取公网 IP"
                    className="w-full px-3 py-2 border rounded-lg bg-background"
                  />
                  <p className="text-xs text-muted-foreground mt-1">
                    留空将自动获取公网 IP（每5分钟更新），也可手动填写固定 IP
                  </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">IPv4 掩码长度</label>
                    <select
                      value={config.ecs?.ipv4_source_mask || 24}
                      onChange={(e) =>
                        setConfig({
                          ...config,
                          ecs: { ...config.ecs, ipv4_source_mask: parseInt(e.target.value) },
                        })
                      }
                      className="w-full px-3 py-2 border rounded-lg bg-background"
                    >
                      <option value={32}>/32 - 精确到主机</option>
                      <option value={24}>/24 - 精确到子网（推荐）</option>
                      <option value={16}>/16 - 精确到城市</option>
                      <option value={8}>/8 - 精确到国家</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-2">IPv6 掩码长度</label>
                    <select
                      value={config.ecs?.ipv6_source_mask || 56}
                      onChange={(e) =>
                        setConfig({
                          ...config,
                          ecs: { ...config.ecs, ipv6_source_mask: parseInt(e.target.value) },
                        })
                      }
                      className="w-full px-3 py-2 border rounded-lg bg-background"
                    >
                      <option value={128}>/128 - 精确到主机</option>
                      <option value={56}>/56 - 精确到子网（推荐）</option>
                      <option value={48}>/48 - 精确到站点</option>
                      <option value={32}>/32 - 精确到 ISP</option>
                    </select>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-2">默认分组</label>
              <select
                value={config.proxy.default_group}
                onChange={(e) =>
                  setConfig({
                    ...config,
                    proxy: { ...config.proxy, default_group: e.target.value },
                  })
                }
                className="w-full px-3 py-2 border rounded-lg bg-background"
              >
                <option value="">使用所有服务器（不筛选）</option>
                {(config.server_groups || []).map((g) => (
                  <option key={g.name} value={g.name}>{g.description || g.name}</option>
                ))}
              </select>
              <p className="text-xs text-muted-foreground mt-1">
                未匹配任何规则时，默认使用此分组的服务器解析
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* DNS选择策略 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Zap className="w-5 h-5 text-primary" />
            <h3 className="font-semibold">DNS 选择策略</h3>
          </div>
          <div className="flex items-center gap-2">
            {lastTestTime && (
              <span className="text-xs text-muted-foreground">上次测试: {lastTestTime}</span>
            )}
            <button
              onClick={handleTestLatency}
              disabled={testingLatency}
              className="flex items-center gap-2 px-3 py-1.5 text-sm bg-secondary text-secondary-foreground rounded-lg hover:bg-secondary/80 disabled:opacity-50"
            >
              <Timer className={`w-4 h-4 ${testingLatency ? "animate-spin" : ""}`} />
              {testingLatency ? "测试中..." : "测试延迟"}
            </button>
          </div>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {[
              {
                value: "sequential" as DnsStrategy,
                title: "按顺序",
                desc: "使用第一个可用的DNS服务器",
              },
              {
                value: "fastest" as DnsStrategy,
                title: "最快响应",
                desc: "选择响应最快的DNS服务器",
              },
              {
                value: "load_balance" as DnsStrategy,
                title: "负载均衡",
                desc: "轮询分配请求到多个服务器",
              },
              {
                value: "parallel" as DnsStrategy,
                title: "并行请求",
                desc: "同时请求多个服务器，使用最快响应",
              },
            ].map((s) => (
              <label
                key={s.value}
                className={`p-4 border rounded-lg cursor-pointer transition-all ${
                  config.strategy === s.value
                    ? "border-primary bg-primary/5"
                    : "hover:bg-muted/50"
                }`}
              >
                <div className="flex items-center gap-3">
                  <input
                    type="radio"
                    name="strategy"
                    value={s.value}
                    checked={config.strategy === s.value}
                    onChange={() => setConfig({ ...config, strategy: s.value })}
                    className="text-primary"
                  />
                  <div>
                    <p className="font-medium">{s.title}</p>
                    <p className="text-xs text-muted-foreground">{s.desc}</p>
                  </div>
                </div>
              </label>
            ))}
          </div>

          {/* 自动测速间隔设置 */}
          <div className="mt-4 p-3 bg-muted/50 rounded-lg">
            <div className="flex items-center justify-between">
              <div>
                <h4 className="text-sm font-medium">自动测速间隔</h4>
                <p className="text-xs text-muted-foreground">设为 0 禁用自动测速</p>
              </div>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  value={config.latency_test_interval || 0}
                  onChange={(e) =>
                    setConfig({
                      ...config,
                      latency_test_interval: parseInt(e.target.value) || 0,
                    })
                  }
                  className="w-20 px-2 py-1 border rounded bg-background text-sm text-right"
                  min="0"
                  step="60"
                />
                <span className="text-sm text-muted-foreground">秒</span>
              </div>
            </div>
          </div>

          {/* 延迟测试结果 */}
          {latencyResults.length > 0 && (
            <div className="mt-4 p-3 bg-muted/50 rounded-lg">
              <h4 className="text-sm font-medium mb-2">延迟测试结果</h4>
              <div className="space-y-2">
                {latencyResults.map((result, index) => (
                  <div key={index} className="flex items-center justify-between text-sm">
                    <div className="flex items-center gap-2">
                      <span className="text-muted-foreground">#{index + 1}</span>
                      <span className="font-medium">{result.name}</span>
                      <span className="text-muted-foreground">({result.ip})</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {result.latency_ms !== undefined ? (
                        <span className={`font-mono font-bold ${getLatencyColor(result.latency_ms)}`}>
                          {result.latency_ms} ms
                        </span>
                      ) : (
                        <span className="text-red-500 text-xs">{result.error || "失败"}</span>
                      )}
                      {index === 0 && result.latency_ms !== undefined && (
                        <span className="text-xs bg-green-100 text-green-700 px-1.5 py-0.5 rounded">
                          最快
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* 上游DNS服务器 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Server className="w-5 h-5 text-primary" />
            <h3 className="font-semibold">上游 DNS 服务器</h3>
          </div>
          <button
            onClick={handleAddServer}
            className="flex items-center gap-2 px-3 py-1.5 text-sm bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
          >
            <Plus className="w-4 h-4" />
            添加服务器
          </button>
        </div>
        <div className="p-4 space-y-3">
          {config.upstream.map((server, index) => (
            <div key={index} className="p-4 border rounded-lg space-y-3">
              <div className="flex items-center gap-3">
                <input
                  type="checkbox"
                  checked={server.enabled}
                  onChange={() => handleToggleServer(index)}
                  className="w-4 h-4"
                />
                <input
                  type="text"
                  value={server.name}
                  onChange={(e) => handleServerChange(index, "name", e.target.value)}
                  className="flex-1 px-3 py-1.5 border rounded bg-background text-sm"
                  placeholder="服务器名称"
                />
                <select
                  value={server.group || "default"}
                  onChange={(e) => handleServerChange(index, "group", e.target.value)}
                  className="px-3 py-1.5 border rounded bg-background text-sm"
                >
                  {(config.server_groups || []).map((g) => (
                    <option key={g.name} value={g.name}>{g.description || g.name}</option>
                  ))}
                </select>
                <select
                  value={server.protocol}
                  onChange={(e) => handleProtocolChange(index, e.target.value as DnsProtocol)}
                  className="px-3 py-1.5 border rounded bg-background text-sm"
                >
                  <option value="udp">UDP</option>
                  <option value="tcp">TCP</option>
                  <option value="doh">DoH</option>
                  <option value="dot">DoT</option>
                </select>
                <button
                  onClick={() => handleRemoveServer(index)}
                  className="p-1.5 text-muted-foreground hover:text-destructive"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {server.protocol === "doh" ? (
                  /* DoH: 只需要 URL */
                  <div className="md:col-span-3">
                    <label className="block text-xs text-muted-foreground mb-1">DoH URL</label>
                    <input
                      type="text"
                      value={server.doh_url || ""}
                      onChange={(e) => handleServerChange(index, "doh_url", e.target.value)}
                      className="w-full px-3 py-1.5 border rounded bg-background text-sm"
                      placeholder="https://cloudflare-dns.com/dns-query"
                    />
                    <p className="text-xs text-muted-foreground mt-1">DoH 协议使用 URL 访问，无需填写 IP 地址</p>
                  </div>
                ) : server.protocol === "dot" ? (
                  /* DoT: 主机名 + 端口 */
                  <>
                    <div className="md:col-span-2">
                      <label className="block text-xs text-muted-foreground mb-1">主机名（域名或 IP）</label>
                      <input
                        type="text"
                        value={server.ip}
                        onChange={(e) => handleServerChange(index, "ip", e.target.value)}
                        className="w-full px-3 py-1.5 border rounded bg-background text-sm font-mono"
                        placeholder="cloudflare-dns.com 或 1.1.1.1"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-muted-foreground mb-1">端口</label>
                      <input
                        type="number"
                        value={server.port || 853}
                        onChange={(e) => handleServerChange(index, "port", parseInt(e.target.value) || 853)}
                        className="w-full px-3 py-1.5 border rounded bg-background text-sm font-mono"
                        placeholder="853"
                      />
                    </div>
                  </>
                ) : (
                  /* UDP/TCP: IP + 端口 */
                  <>
                    <div>
                      <label className="block text-xs text-muted-foreground mb-1">IP 地址</label>
                      <input
                        type="text"
                        value={server.ip}
                        onChange={(e) => handleServerChange(index, "ip", e.target.value)}
                        className="w-full px-3 py-1.5 border rounded bg-background text-sm font-mono"
                        placeholder="1.1.1.1"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-muted-foreground mb-1">端口</label>
                      <input
                        type="number"
                        value={server.port}
                        onChange={(e) => handleServerChange(index, "port", parseInt(e.target.value) || 53)}
                        className="w-full px-3 py-1.5 border rounded bg-background text-sm font-mono"
                      />
                    </div>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* 服务器分组管理 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Database className="w-5 h-5 text-primary" />
            <h3 className="font-semibold">服务器分组</h3>
          </div>
          <button
            onClick={() => {
              if (!config) return;
              const name = prompt("分组名称 (英文，如 custom):");
              if (!name) return;
              const desc = prompt("分组描述:") || name;
              if (config.server_groups.some((g) => g.name === name)) {
                alert("该分组已存在");
                return;
              }
              setConfig({
                ...config,
                server_groups: [...(config.server_groups || []), { name, description: desc }],
              });
            }}
            className="flex items-center gap-2 px-3 py-1.5 text-sm bg-primary text-primary-foreground rounded-lg hover:bg-primary/90"
          >
            <Plus className="w-4 h-4" />
            添加分组
          </button>
        </div>
        <div className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3">
            {(config.server_groups || []).map((group) => {
              const serverCount = config.upstream.filter((s) => (s.group || "default") === group.name).length;
              return (
                <div key={group.name} className="p-3 border rounded-lg">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium text-sm">{group.description || group.name}</p>
                      <p className="text-xs text-muted-foreground">{group.name} · {serverCount} 个服务器</p>
                    </div>
                    {group.name !== "default" && group.name !== "domestic" && group.name !== "proxy" && (
                      <button
                        onClick={() => {
                          if (!config) return;
                          setConfig({
                            ...config,
                            server_groups: config.server_groups.filter((g) => g.name !== group.name),
                          });
                        }}
                        className="p-1 text-muted-foreground hover:text-destructive"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* 预设服务器 */}
      <div className="bg-card rounded-xl border p-4">
        <h4 className="font-semibold mb-3">快速添加预设服务器</h4>
        <div className="space-y-3">
          <div>
            <p className="text-xs text-muted-foreground mb-2">🇨🇳 国内 DNS（直连）</p>
            <div className="flex flex-wrap gap-2">
              {[
                { name: "阿里 DoH", ip: "223.5.5.5", protocol: "doh" as DnsProtocol, doh_url: "https://dns.alidns.com/dns-query", group: "domestic" },
                { name: "114DNS", ip: "114.114.114.114", protocol: "udp" as DnsProtocol, group: "domestic" },
                { name: "腾讯 DNS", ip: "119.29.29.29", protocol: "udp" as DnsProtocol, group: "domestic" },
              ].map((preset) => (
                <button
                  key={preset.name}
                  onClick={() => {
                    if (!config) return;
                    const exists = config.upstream.some((s) => s.ip === preset.ip && s.protocol === preset.protocol);
                    if (!exists) {
                      setConfig({
                        ...config,
                        upstream: [
                          ...config.upstream,
                          { ...preset, port: preset.protocol === "doh" ? 443 : 53, enabled: true },
                        ],
                      });
                    }
                  }}
                  className="px-3 py-1.5 text-sm border rounded-lg hover:bg-muted"
                >
                  + {preset.name}
                </button>
              ))}
            </div>
          </div>
          <div>
            <p className="text-xs text-muted-foreground mb-2">🔗 代理 DNS（代理）</p>
            <div className="flex flex-wrap gap-2">
              {[
                { name: "Clash DNS", ip: "127.0.0.1", port: 1053, protocol: "udp" as DnsProtocol, group: "proxy" },
              ].map((preset) => (
                <button
                  key={preset.name}
                  onClick={() => {
                    if (!config) return;
                    const exists = config.upstream.some((s) => s.ip === preset.ip && s.port === preset.port);
                    if (!exists) {
                      setConfig({
                        ...config,
                        upstream: [
                          ...config.upstream,
                          { ...preset, enabled: true, doh_url: "" },
                        ],
                      });
                    }
                  }}
                  className="px-3 py-1.5 text-sm border rounded-lg hover:bg-muted"
                >
                  + {preset.name}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* 保存按钮 */}
      <div className="flex justify-end">
        <button
          onClick={handleSave}
          disabled={saving}
          className="flex items-center gap-2 px-6 py-3 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 disabled:opacity-50"
        >
          <Save className="w-5 h-5" />
          {saving ? "保存中..." : "保存设置"}
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { api, DnsStats, DnsQueryLog, AppConfig, TrafficStats, CacheStats, TunStatus } from "../lib/api";
import {
  Activity,
  Server,
  Shield,
  Zap,
  Clock,
  Globe,
  Play,
  Square,
  Loader2,
  BarChart3,
  Wifi,
  Power,
} from "lucide-react";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
} from "recharts";

export default function Dashboard() {
  const [stats, setStats] = useState<DnsStats>({
    total_queries: 0,
    blocked_queries: 0,
    cached_queries: 0,
    avg_latency: 0,
    is_running: false,
  });
  const [logs, setLogs] = useState<DnsQueryLog[]>([]);
  const [config, setConfig] = useState<AppConfig | null>(null);
  const [trafficStats, setTrafficStats] = useState<TrafficStats | null>(null);
  const [cacheStats, setCacheStats] = useState<CacheStats | null>(null);
  const [loading, setLoading] = useState(false);
  const [tunLoading, setTunLoading] = useState(false);
  const [initializing, setInitializing] = useState(true);
  const [tunStatus, setTunStatus] = useState<TunStatus>({
    active: false,
    starting: false,
    interface_name: "",
    ip_address: "",
    dns_redirected: false,
    packets_processed: 0,
  });

  // 刷新状态
  const refreshStatus = useCallback(async () => {
    try {
      const [newStats, newLogs, newConfig, newTrafficStats, newCacheStats, newTunStatus] = await Promise.all([
        api.getStats(),
        api.getLogs(),
        api.getConfig(),
        api.getTrafficStats(),
        api.getCacheStats(),
        api.getTunStatus().catch(() => ({ active: false, starting: false, interface_name: "", ip_address: "", dns_redirected: false, packets_processed: 0 })),
      ]);
      setStats(newStats);
      setLogs(newLogs.slice(0, 10));
      setConfig(newConfig);
      setTrafficStats(newTrafficStats);
      setCacheStats(newCacheStats);
      setTunStatus(newTunStatus);
    } catch (e) {
      console.error("获取状态失败:", e);
    } finally {
      setInitializing(false);
    }
  }, []);

  // 定时刷新
  useEffect(() => {
    refreshStatus();
    const interval = setInterval(refreshStatus, 1000);
    return () => clearInterval(interval);
  }, [refreshStatus]);

  // 启动/停止服务
  const toggleService = async () => {
    setLoading(true);
    try {
      if (stats.is_running) {
        await api.stopServer();
        // 等待端口释放
        await new Promise(resolve => setTimeout(resolve, 300));
      } else {
        await api.startServer();
      }
      // 等待一下再刷新状态
      await new Promise(resolve => setTimeout(resolve, 500));
      await refreshStatus();
    } catch (e: any) {
      const msg = String(e);
      if (msg.includes("10048") || msg.includes("address already in use")) {
        // 端口被占用，尝试重启
        try {
          await api.stopServer();
          await new Promise(resolve => setTimeout(resolve, 1000));
          await api.startServer();
          await new Promise(resolve => setTimeout(resolve, 500));
          await refreshStatus();
        } catch (e2) {
          alert("启动失败: " + e2);
        }
      } else {
        alert("操作失败: " + e);
      }
    } finally {
      setLoading(false);
    }
  };

  // 启动/停止 TUN
  const toggleTun = async () => {
    setTunLoading(true);

    // 立即显示启动中状态
    if (!tunStatus.active) {
      setTunStatus(prev => ({ ...prev, starting: true }));
    }

    try {
      if (tunStatus.active) {
        await api.stopTun();
      } else {
        await api.startTun();
      }
      // 持续刷新直到状态稳定
      for (let i = 0; i < 10; i++) {
        await new Promise(resolve => setTimeout(resolve, 500));
        await refreshStatus();
        // 如果状态已经不是启动中，可以提前退出
        if (!tunStatus.starting && tunStatus.active) break;
      }
    } catch (e) {
      alert("TUN 操作失败: " + e);
      // 出错时刷新真实状态
      await refreshStatus();
    } finally {
      setTunLoading(false);
    }
  };

  if (initializing) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
        <span className="ml-2">加载中...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 服务控制卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* DNS 代理服务 */}
        <div className="bg-card rounded-xl border p-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-semibold">DNS 代理服务</h3>
              <p className="text-sm text-muted-foreground">
                {stats.is_running ? `运行中 · 监听端口 ${config?.proxy.listen_port || 53}` : "服务未启动"}
              </p>
            </div>
            <button
              onClick={toggleService}
              disabled={loading}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all text-sm
                ${
                  stats.is_running
                    ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    : "bg-primary text-primary-foreground hover:bg-primary/90"
                }
                ${loading ? "opacity-70 cursor-wait" : ""}
              `}
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  处理中
                </>
              ) : stats.is_running ? (
                <>
                  <Square className="w-4 h-4" />
                  停止
                </>
              ) : (
                <>
                  <Play className="w-4 h-4" />
                  启动
                </>
              )}
            </button>
          </div>

          {stats.is_running && (
            <div className="mt-3 flex items-center gap-2 text-sm text-green-600">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
              <span>DNS 服务正常运行</span>
            </div>
          )}
        </div>

        {/* TUN 服务 */}
        <div className="bg-card rounded-xl border p-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-semibold flex items-center gap-2">
                <Wifi className="w-5 h-5" />
                TUN 模式
              </h3>
              <p className="text-sm text-muted-foreground">
                {tunStatus.active
                  ? `运行中 · ${tunStatus.interface_name}`
                  : tunStatus.starting
                  ? "启动中..."
                  : "未启用"}
              </p>
            </div>
            <button
              onClick={toggleTun}
              disabled={tunLoading || tunStatus.starting}
              className={`
                flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all text-sm
                ${
                  tunStatus.active
                    ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    : "bg-primary text-primary-foreground hover:bg-primary/90"
                }
                ${tunLoading || tunStatus.starting ? "opacity-70 cursor-wait" : ""}
              `}
            >
              {tunLoading || tunStatus.starting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  {tunStatus.starting ? "启动中" : "处理中"}
                </>
              ) : tunStatus.active ? (
                <>
                  <Power className="w-4 h-4" />
                  停止
                </>
              ) : (
                <>
                  <Zap className="w-4 h-4" />
                  启动
                </>
              )}
            </button>
          </div>

          {tunStatus.active && (
            <div className="mt-3 flex items-center gap-4 text-sm">
              <div className="flex items-center gap-2 text-green-600">
                <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                <span>TUN 正常运行</span>
              </div>
              {tunStatus.ip_address && (
                <span className="text-muted-foreground">IP: {tunStatus.ip_address}</span>
              )}
            </div>
          )}

          {!tunStatus.active && !tunStatus.starting && (
            <div className="mt-3 text-xs text-muted-foreground">
              在「网络设置」页面配置 TUN 参数
            </div>
          )}
        </div>
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="总查询数" value={stats.total_queries.toLocaleString()} icon={Activity} color="blue" />
        <StatCard title="阻止查询" value={stats.blocked_queries.toLocaleString()} icon={Shield} color="red" />
        <StatCard title="平均延迟" value={`${stats.avg_latency.toFixed(1)}ms`} icon={Zap} color="yellow" />
        <StatCard title="缓存命中" value={stats.cached_queries.toLocaleString()} icon={Server} color="green" />
      </div>

      {/* 流量图表区域 */}
      {trafficStats && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* 请求量时间线 */}
          <div className="bg-card rounded-xl border p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold flex items-center gap-2">
                <BarChart3 className="w-5 h-5" />
                请求量趋势
              </h3>
              <span className="text-sm text-muted-foreground">
                QPS: {trafficStats.queries_per_second.toFixed(1)}
              </span>
            </div>
            {trafficStats.timeline.length > 0 ? (
              <ResponsiveContainer width="100%" height={200}>
                <AreaChart data={trafficStats.timeline}>
                  <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
                  <XAxis
                    dataKey="time"
                    tick={{ fontSize: 12 }}
                    interval="preserveStartEnd"
                  />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: 'var(--card)',
                      border: '1px solid var(--border)',
                      borderRadius: '8px',
                    }}
                  />
                  <Area
                    type="monotone"
                    dataKey="total"
                    stackId="1"
                    stroke="#3b82f6"
                    fill="#3b82f6"
                    fillOpacity={0.3}
                    name="总查询"
                  />
                  <Area
                    type="monotone"
                    dataKey="blocked"
                    stackId="2"
                    stroke="#ef4444"
                    fill="#ef4444"
                    fillOpacity={0.3}
                    name="阻止"
                  />
                  <Area
                    type="monotone"
                    dataKey="cached"
                    stackId="3"
                    stroke="#22c55e"
                    fill="#22c55e"
                    fillOpacity={0.3}
                    name="缓存"
                  />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-[200px] flex items-center justify-center text-muted-foreground">
                暂无数据
              </div>
            )}
          </div>

          {/* Top 10 域名 */}
          <div className="bg-card rounded-xl border p-4">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <Globe className="w-5 h-5" />
              Top 10 热门域名
            </h3>
            {trafficStats.top_domains.length > 0 ? (
              <ResponsiveContainer width="100%" height={200}>
                <BarChart
                  data={trafficStats.top_domains}
                  layout="vertical"
                  margin={{ left: 80 }}
                >
                  <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
                  <XAxis type="number" tick={{ fontSize: 12 }} />
                  <YAxis
                    type="category"
                    dataKey="domain"
                    tick={{ fontSize: 11 }}
                    width={80}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: 'var(--card)',
                      border: '1px solid var(--border)',
                      borderRadius: '8px',
                    }}
                  />
                  <Bar dataKey="count" fill="#8b5cf6" radius={[0, 4, 4, 0]} name="查询次数" />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-[200px] flex items-center justify-center text-muted-foreground">
                暂无数据
              </div>
            )}
          </div>

          {/* 延迟分布 */}
          <div className="bg-card rounded-xl border p-4">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <Zap className="w-5 h-5" />
              响应延迟分布
            </h3>
            {trafficStats.latency_dist.some(d => d.count > 0) ? (
              <ResponsiveContainer width="100%" height={200}>
                <BarChart data={trafficStats.latency_dist}>
                  <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
                  <XAxis dataKey="range" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: 'var(--card)',
                      border: '1px solid var(--border)',
                      borderRadius: '8px',
                    }}
                  />
                  <Bar dataKey="count" fill="#f59e0b" radius={[4, 4, 0, 0]} name="查询次数" />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-[200px] flex items-center justify-center text-muted-foreground">
                暂无数据
              </div>
            )}
          </div>

          {/* 查询类型分布（新增） */}
          <div className="bg-card rounded-xl border p-4">
            <h3 className="font-semibold mb-4 flex items-center gap-2">
              <Activity className="w-5 h-5" />
              查询统计
            </h3>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="text-center p-3 bg-muted/50 rounded-lg">
                  <p className="text-2xl font-bold text-blue-600">
                    {trafficStats.total_queries.toLocaleString()}
                  </p>
                  <p className="text-sm text-muted-foreground">总查询数</p>
                </div>
                <div className="text-center p-3 bg-muted/50 rounded-lg">
                  <p className="text-2xl font-bold text-green-600">
                    {trafficStats.queries_per_second.toFixed(1)}
                  </p>
                  <p className="text-sm text-muted-foreground">QPS</p>
                </div>
              </div>
              <div className="text-sm text-muted-foreground text-center">
                统计时间: 最近 60 分钟
              </div>
            </div>
          </div>

          {/* 缓存统计 */}
          {cacheStats && (
            <div className="bg-card rounded-xl border p-4">
              <h3 className="font-semibold mb-4 flex items-center gap-2">
                <Server className="w-5 h-5" />
                缓存统计
              </h3>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="text-center p-3 bg-muted/50 rounded-lg">
                    <p className="text-2xl font-bold text-purple-600">
                      {(cacheStats.hit_rate * 100).toFixed(1)}%
                    </p>
                    <p className="text-sm text-muted-foreground">命中率</p>
                  </div>
                  <div className="text-center p-3 bg-muted/50 rounded-lg">
                    <p className="text-2xl font-bold text-orange-600">
                      {cacheStats.current_size}/{cacheStats.max_size}
                    </p>
                    <p className="text-sm text-muted-foreground">缓存条目</p>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div className="flex justify-between px-2">
                    <span className="text-muted-foreground">命中</span>
                    <span className="font-medium text-green-600">{cacheStats.cache_hits.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between px-2">
                    <span className="text-muted-foreground">未命中</span>
                    <span className="font-medium text-red-600">{cacheStats.cache_misses.toLocaleString()}</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* 最近查询 */}
      <div className="bg-card rounded-xl border">
        <div className="p-4 border-b">
          <h3 className="font-semibold">最近查询</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full table-fixed min-w-[700px]">
            <thead>
              <tr className="border-b bg-muted/50">
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[15%]">时间</th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[30%]">域名</th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[10%]">类型</th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[20%]">响应</th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[15%]">上游</th>
                <th className="text-left p-3 text-sm font-medium text-muted-foreground w-[10%]">状态</th>
              </tr>
            </thead>
            <tbody>
              {logs.length === 0 ? (
                <tr>
                  <td colSpan={6} className="p-8 text-center text-muted-foreground">
                    暂无查询记录
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <tr key={log.id} className="border-b hover:bg-muted/50">
                    <td className="p-3 text-sm whitespace-nowrap">
                      <div className="flex items-center gap-2 truncate">
                        <Clock className="w-4 h-4 text-muted-foreground shrink-0" />
                        <span className="truncate">{log.timestamp}</span>
                      </div>
                    </td>
                    <td className="p-3 text-sm font-medium">
                      <div className="flex items-center gap-2">
                        <Globe className="w-4 h-4 text-muted-foreground shrink-0" />
                        <span className="truncate">{log.domain}</span>
                      </div>
                    </td>
                    <td className="p-3 text-sm whitespace-nowrap">
                      <span className="px-2 py-1 rounded bg-muted text-xs font-mono">{log.query_type}</span>
                    </td>
                    <td className="p-3 text-sm font-mono truncate">{log.response}</td>
                    <td className="p-3 text-sm text-muted-foreground">
                      <div className="flex items-center gap-1 truncate">
                        <span className="truncate">{log.upstream}</span>
                        {log.group && (
                          <span className={`shrink-0 px-1.5 py-0.5 rounded text-[10px] ${
                            log.group === "domestic" ? "bg-blue-100 text-blue-600" :
                            log.group === "proxy" ? "bg-orange-100 text-orange-600" :
                            "bg-gray-100 text-gray-600"
                          }`}>
                            {log.group === "domestic" ? "直连" : log.group === "proxy" ? "代理" : log.group}
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="p-3 text-sm whitespace-nowrap">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        log.action === "success" ? "bg-green-100 text-green-700" :
                        log.action === "blocked" ? "bg-red-100 text-red-700" :
                        "bg-blue-100 text-blue-700"
                      }`}>
                        {log.action === "success" ? "成功" : log.action === "blocked" ? "阻止" : "缓存"}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 系统信息 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">上游 DNS 服务器</h4>
          <div className="space-y-2">
            {config ? (
              config.upstream.filter((s) => s.enabled).map((server, i) => (
                <div key={i} className="flex items-center justify-between">
                  <span className="text-muted-foreground text-sm">
                    {server.name}
                    <span className="ml-1.5 text-xs text-muted-foreground/60">({server.group || "default"})</span>
                  </span>
                  <span className="font-mono text-sm">{server.ip}:{server.port}</span>
                </div>
              ))
            ) : (
              <p className="text-sm text-muted-foreground">加载中...</p>
            )}
            {config && config.upstream.filter((s) => s.enabled).length === 0 && (
              <p className="text-sm text-muted-foreground">无启用的服务器</p>
            )}
          </div>
        </div>

        <div className="bg-card rounded-xl border p-4">
          <h4 className="font-semibold mb-3">系统信息</h4>
          <div className="space-y-3 text-sm">
            <InfoItem label="监听地址" value={config ? `${config.proxy.listen_address}:${config.proxy.listen_port}` : "-"} />
            <InfoItem label="策略" value={config ? config.strategy : "-"} />
            <InfoItem label="运行状态" value={stats.is_running ? "运行中" : "已停止"} />
            <div className="pt-2">
              <button
                onClick={async () => {
                  try {
                    await api.clearCache();
                    await refreshStatus();
                  } catch (e) {
                    console.error("清空缓存失败:", e);
                  }
                }}
                className="px-3 py-1.5 text-sm bg-muted hover:bg-muted/80 rounded-md transition-colors"
              >
                清空 DNS 缓存
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function StatCard({ title, value, icon: Icon, color }: {
  title: string; value: string; icon: any; color: string;
}) {
  const colors: Record<string, string> = {
    blue: "bg-blue-50 text-blue-600",
    red: "bg-red-50 text-red-600",
    yellow: "bg-yellow-50 text-yellow-600",
    green: "bg-green-50 text-green-600",
  };

  return (
    <div className="bg-card rounded-xl border p-4">
      <div className="flex items-center justify-between">
        <div className={`p-2 rounded-lg ${colors[color]}`}>
          <Icon className="w-5 h-5" />
        </div>
      </div>
      <div className="mt-3">
        <p className="text-2xl font-bold">{value}</p>
        <p className="text-sm text-muted-foreground">{title}</p>
      </div>
    </div>
  );
}

function InfoItem({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-muted-foreground">{label}</span>
      <span className="font-mono">{value}</span>
    </div>
  );
}

